const log = find_block({ name: 'oak_log', max_distance: 32 });
if (!log) {
  return { done: false, detail: 'no oak log within 32 blocks' };
}
await dig(log.x, log.y, log.z);
const opened = await open_chest();
if (!opened.ok) {
  return { done: false, detail: opened.detail };
}
const put = await deposit('oak_log', 1);
if (!put.ok) {
  return { done: false, detail: put.detail };
}
return { done: true, detail: 'mined an oak log and put it in the chest' };
